// Ported from the Node app's Sequelize model MasterItem (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class MasterItemConfiguration : IEntityTypeConfiguration<MasterItem>
{
    public void Configure(EntityTypeBuilder<MasterItem> builder)
    {
        builder.ToTable("master_items");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Type).HasColumnName("type").HasColumnType("nvarchar(30)").HasMaxLength(30).IsRequired();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Required).HasColumnName("required");
        builder.Property(e => e.Active).HasColumnName("active");
        builder.Property(e => e.SortOrder).HasColumnName("sort_order").HasDefaultValueSql("0");
        builder.HasIndex(e => new { e.Type, e.Name }).IsUnique().HasDatabaseName("uq_master_item");
    }
}
